def ca_gu_of(addr):
    """‘충청남도 천안시 동남구 …’에서 자치구를 읽는다."""
    if not addr:
        return None
    parts = addr.split()
    for i, tok in enumerate(parts):
        if tok == "천안시" and i + 1 < len(parts) and parts[i + 1].endswith("구"):
            return parts[i + 1]
    return None


