def asan_dong_of(addr, name=None):
    """아산시 주소에서 법정동·읍·면을 읽는다 — '아산시' 다음 낱말이 동·읍·면이다."""
    if addr:
        m = re.search(r"아산시\s*([가-힣]{1,6}(?:동|읍|면))", addr)
        if m:
            return m.group(1)
    if name:
        m = re.search(r",\s*([가-힣]{1,5}(?:동|읍|면))\s+\d", name)
        if m:
            return m.group(1)
    return None


def asan_fee(row, name, note_bits, fee_diff):
    """아산시 공영주차장 한 곳의 요금 — 등록값·특기사항을 쓰고 조례 별표와 대조한다."""
    raw_type = (row.get("요금정보") or "").strip()
    base_min = to_int(row.get("주차기본시간"))
    base_fee = to_int(row.get("주차기본요금"))
    unit_min = to_int(row.get("추가단위시간"))
    unit_fee = to_int(row.get("추가단위요금"))
    day = to_int(row.get("1일주차권요금"))
    month = to_int(row.get("월정기권요금"))
    note = row.get("특기사항") or ""
    grade = (row.get("급지구분") or "").strip()
    ptype = (row.get("주차장유형") or "").strip()
    fee = {"type": "유료", "base_min": None, "base_fee": None, "unit_min": None, "unit_fee": None,
           "daily_fee": None, "daily_hours": None, "cap_fee": None, "cap_src": None,
           "monthly": None, "monthly_all": None, "monthly_label": None,
           "grade": None, "grade_label": None, "std_grade": grade or None,
           "deduct_min": None, "free_min": None, "ticket_only": False, "flat_day": False,
           "mixed": raw_type == "혼합", "progressive": False,
           "pay": (row.get("결제방법") or "").strip(), "std": None}
    if raw_type == "무료":
        fee.update({"type": "무료", "basis": "요금 구분 ‘무료’"})
        if name in ("모종동 제2공영주차장", "모종동 제3공영주차장"):
            fee_diff.append(f"{name}: 표준데이터에는 무료로 등록되어 있으나 2026-11-01 유료화"
                            "(행정예고, 아산시 공고 제2026-3304호)가 고지됨 — 등록값(무료)을"
                            " 표기하고 운영기관 확인 필요")
            note_bits.append("2026년 11월 1일부터 유료로 전환한다는 행정예고가 있었습니다"
                             "(아산시 공고 제2026-3304호) — 표준데이터 등록은 무료이니"
                             " 방문 전 운영기관에 확인하세요")
        return fee
    if raw_type not in ("유료", "혼합"):
        fee.update({"type": "미상", "basis": "요금 칸이 비어 있음"})
        return fee
    if not (base_fee or 0) and not (unit_fee or 0) and not day and not month:
        fee.update({"type": "미상", "basis": "‘유료’로 등록됐지만 요금표 등록값이 없음"})
        fee["std"] = {"base_min": base_min, "base_fee": base_fee, "unit_min": unit_min,
                      "unit_fee": unit_fee, "day": day, "monthly": month}
        return fee
    fee["std"] = {"base_min": base_min, "base_fee": base_fee, "unit_min": unit_min,
                  "unit_fee": unit_fee, "day": day, "monthly": month}
    if ptype == "부설":
        # 공공청사 부설 — 시행규칙 별표: 최초 120분 무료 → 초과 10분 이내 1,000원 →
        #   이후 10분당 200원, 1일 7,000원. 등록 기본 130분 1,000원과 정확히 일치한다.
        fee.update({"base_min": base_min or 130, "base_fee": base_fee,
                    "free_min": 120,
                    "unit_min": unit_min or 10, "unit_fee": unit_fee,
                    "daily_fee": day,
                    "grade_label": "공공청사 부설",
                    "basis": "아산시 공공청사 부설주차장 요금징수 조례 시행규칙 별표"
                             "(최초 120분 무료·이후 10분당 200원)"})
        note_bits.append("공공청사 부설주차장으로, 요금은 평일 08:00~19:00에만 징수하고"
                         " 그 외 시간·휴무일·일요일에는 무료로 개방합니다"
                         "(부설주차장 요금징수 조례 시행규칙 제6조)")
        if month:
            fee["monthly_all"] = month
            fee["monthly"] = month
        return fee
    if name in ASAN_MARKET_NAMES:
        # 전통시장 조례 별표 소관 — 1시간 총액·초과 단위요금은 일치하지만 별표의
        #   '최초 30분 무료' 구간이 등록 표기에 없어 등록값을 유지하고 차이를 명시한다.
        fee.update({"base_min": base_min or 60, "base_fee": base_fee,
                    "unit_min": unit_min or 10, "unit_fee": unit_fee,
                    "daily_fee": day,
                    "grade_label": "전통시장",
                    "basis": "표준데이터 등록요금 — 전통시장 조례 별표(최초 30분 무료·"
                             "30분 초과 1시간 이하 500원)와 1시간 총액은 같지만"
                             " 무료 구간 표기가 달라 운영 근거 확인 중"})
        fee_diff.append(f"{name}: 전통시장 조례 별표는 최초 30분 무료 후 1시간까지 500원이나"
                        f" 등록은 기본 {base_min or 60}분 {base_fee:,}원부터 과금 — 1시간 총액은"
                        " 같고 무료 구간 표기만 달라 등록값 표기")
        note_bits.append("전통시장 주차장으로, 시장 조례 별표에는 최초 30분 무료가 있으나"
                         " 등록 요금표에는 없어 실제 적용은 현장에서 확인하세요")
        if month:
            fee["monthly_all"] = month
            fee["monthly"] = month
        return fee
    if not (base_fee or 0) and not (unit_fee or 0) and month:
        # 캠핑용자동차 전용주차장 — 시간제 등록이 없고 월정기만 있다.
        fee.update({"base_min": None, "base_fee": None, "unit_min": None, "unit_fee": None,
                    "daily_fee": None, "monthly": month, "monthly_all": month,
                    "monthly_label": "종일권 기준 · 아산시민 60,000원(특기사항)",
                    "monthly_only": True,
                    "basis": "표준데이터 등록 월정기(아산시 주차장 조례 별표 1의 1급지"
                             " 종일권과 동일)"})
        fee_diff.append(f"{name}: 시간제 등록 없이 월정기 {month:,}원만 등록 — 별표 1에 캠핑"
                        " 전용 요율은 없고 1급지 종일권과 같은 금액, 특기사항은 아산시민"
                        " 정기권 60,000원을 적고 있어 월정기 전용으로 표기")
        note_bits.append("월정기 전용 주차장으로 시간제는 없습니다 — 종일권 80,000원,"
                         " 아산시민 정기권은 60,000원입니다(특기사항)")
        return fee
    g = ASAN_FEE.get(grade)
    if g:
        # 별표 1 구조 — 최초 30분 무료 → 1시간까지 10분마다 seg_fee → 1시간 초과 over_fee.
        #   등록 기본 60분 요금이 이 구조의 1시간 요금(600원)과 일치하는지 대조한다.
        hour_fee = g["seg_fee"] * 3
        fee.update({"base_min": 30, "base_fee": 0, "free_min": g["free_min"],
                    "unit_min": 10, "unit_fee": g["over_fee"], "progressive": True,
                    "steps": [{"until": 60, "unit_min": 10, "unit_fee": g["seg_fee"]},
                              {"until": None, "unit_min": 10, "unit_fee": g["over_fee"]}],
                    "steps_label": (f"1시간까지 10분당 {g['seg_fee']:,}원 → "
                                    f"1시간 초과 10분당 {g['over_fee']:,}원"),
                    "daily_fee": day or g["day"],
                    "grade": int(grade), "grade_label": f"{grade}급지",
                    "basis": "아산시 주차장 조례 별표 1(등록 기본요금과 일치)"})
        if base_fee and base_fee != hour_fee:
            fee_diff.append(f"{name}: 등록 기본 {base_min}분 {base_fee:,}원 ↔ 별표 1 {grade}급지"
                            f" 구조의 1시간 요금 {hour_fee:,}원 — 등록값 기준으로 표기")
        if day and day != g["day"]:
            fee_diff.append(f"{name}: 1일 등록 {day:,}원 ↔ 별표 1 {grade}급지 {g['day']:,}원")
        note_bits.append(f"요율은 조례 별표 1 기준 최초 30분 무료, 1시간까지 10분마다 "
                         f"{g['seg_fee']:,}원, 1시간 초과 10분마다 {g['over_fee']:,}원입니다")
    else:
        fee.update({"base_min": base_min, "base_fee": base_fee,
                    "unit_min": unit_min, "unit_fee": unit_fee,
                    "daily_fee": day,
                    "basis": "표준데이터 등록요금"})
    if month:
        fee["monthly_all"] = month
        fee["monthly"] = month
        m_pass = re.search(r"정기권\(주간\s*([\d,]+),\s*야간\s*([\d,]+)\)", note)
        if m_pass and g:
            fee["monthly_label"] = (f"종일권 · 주간 {m_pass.group(1)}원·"
                                    f"야간 {m_pass.group(2)}원(특기사항)")
            if int(m_pass.group(1).replace(",", "")) != g["month_day"] or \
                    int(m_pass.group(2).replace(",", "")) != g["month_night"]:
                fee_diff.append(f"{name}: 특기사항 정기권 주간 {m_pass.group(1)}원·야간 "
                                f"{m_pass.group(2)}원 ↔ 별표 1 {grade}급지 주간 "
                                f"{g['month_day']:,}원·야간 {g['month_night']:,}원")
    if raw_type == "혼합":
        note_bits.append("요금 구분이 ‘혼합’이라 요금을 받는 시간에만 계산합니다")
    return fee


def _as_tier_of(lot):
    f = lot["fee"]
    if f.get("grade_label") == "전통시장":
        return "market"
    if f.get("grade_label") == "공공청사 부설":
        return "busul"
    if f.get("monthly_only"):
        return "monthly_only"
    g = f.get("std_grade")
    if g in ("1", "2", "3") and f.get("steps"):
        return f"g{g}"
    return "other"


def asan_fee_table(conf, lots):
    """요금표 — 조례 별표 1 급지 3묶음 + 전통시장 + 부설."""
    paid = [l for l in lots if l["fee"]["type"] in ("유료", "혼합")]
    samples = {}
    for gk, gv in ASAN_FEE.items():
        samples[f"g{gk}"] = {"base_min": 30, "base_fee": 0, "free_min": 30, "unit_min": 10,
                             "unit_fee": gv["over_fee"], "daily_fee": gv["day"],
                             "steps": [{"until": 60, "unit_min": 10, "unit_fee": gv["seg_fee"]},
                                       {"until": None, "unit_min": 10, "unit_fee": gv["over_fee"]}]}
    samples["market"] = {"base_min": 60, "base_fee": 500, "unit_min": 10, "unit_fee": 200,
                         "daily_fee": None}
    samples["busul"] = {"base_min": 130, "base_fee": 1000, "free_min": 120, "unit_min": 10,
                        "unit_fee": 200, "daily_fee": 7000}
    labels = {
        "g1": ("1급지", "최초 30분 무료 → 1시간까지 10분마다 200원 → 1시간 초과 10분마다 300원"),
        "g2": ("2급지", "최초 30분 무료 → 1시간까지 10분마다 200원 → 1시간 초과 10분마다 300원"),
        "g3": ("3급지", "최초 30분 무료 → 1시간까지 10분마다 100원 → 1시간 초과 10분마다 200원"),
        "market": ("전통시장(온양온천시장·온천역)", "기본 60분 500원 → 10분마다 200원 (별표는 최초 30분 무료)"),
        "busul": ("공공청사 부설(시청·행정복지센터)", "최초 120분 무료 → 130분 1,000원 → 10분마다 200원"),
    }
    months = {"g1": 80_000, "g2": 70_000, "g3": 30_000, "market": None, "busul": None}
    rows = []
    for key in ("g1", "g2", "g3", "market", "busul"):
        gl = [l for l in paid if _as_tier_of(l) == key]
        if not gl:
            continue
        sf = samples[key]
        rows.append({"label": labels[key][0], "grade": key,
                     "unit_label": labels[key][1],
                     "hour": sj_charge(sf, 60), "two_hour": sj_charge(sf, 120),
                     "day": sf["daily_fee"], "month": months[key],
                     "lots": len(gl)})
    ord_rows = [
        {"label": "1급지", "base": 0, "unit": 200, "over": 300, "day": ASAN_FEE["1"]["day"],
         "month": ASAN_FEE["1"]["month_all"]},
        {"label": "2급지", "base": 0, "unit": 200, "over": 300, "day": ASAN_FEE["2"]["day"],
         "month": ASAN_FEE["2"]["month_all"]},
        {"label": "3급지", "base": 0, "unit": 100, "over": 200, "day": ASAN_FEE["3"]["day"],
         "month": ASAN_FEE["3"]["month_all"]},
    ]
    corp = {
        "paid": len([l for l in paid if l["list_mode"] == "card"]),
        "free": len([l for l in lots if l["fee"]["type"] == "무료"]),
        "unknown": len([l for l in lots if l["fee"]["type"] == "미상"]),
        "street_paid": len([l for l in paid if l["list_mode"] == "street"]),
    }
    return {
        "style": "asan_grade",
        "unit_min": 10,
        "base_min": 30,
        "applies": conf["ordinance"][2],
        "rows": rows,
        "ord_rows": ord_rows,
        "corp": corp,
        "windows": [{"group": "공통", "hours": "주차장별 운영시간",
                     "free": ("요금은 표준데이터에 등록된 주차장별 운영시간·특기사항을 "
                              "카드에 그대로 적었습니다")}],
        "notes": conf["notes"],
        "corp_extra": corp,
        "basis": (f"{conf['ordinance'][0]}({conf['ordinance'][2]}) · "
                  "「아산시 전통시장 및 상점가 주차장 관리ㆍ운영에 관한 조례」 별표 · "
                  "「아산시 공공청사 부설주차장 요금징수 조례」 시행규칙 별표 · "
                  "전국주차장정보표준데이터(2026-04-16 기준) 등록값·특기사항 대조"),
    }


def asan_quality(conf, std_all, rows_std, lots, excluded, merged, note_fixed, fee_diff,
                 space_diff, dong_fixed, coord_fixed):
    card = [l for l in lots if l["list_mode"] == "card"]
    street = [l for l in lots if l["list_mode"] == "street"]
    paid = [l for l in lots if l["fee"]["type"] in ("유료", "혼합")]
    free = [l for l in lots if l["fee"]["type"] == "무료"]
    unknown = [l for l in lots if l["fee"]["type"] == "미상"]
    return {
        "generated_at": NOW.strftime("%Y-%m-%d %H:%M"),
        "원자료_전국행수": len(std_all),
        "원자료_행수": len(rows_std),
        f"원자료_{conf['city']}행수": len(rows_std),
        "원자료_받은행수": len(rows_std),
        "구별": {"아산시": len(card)},
        "민영_제외": len([e for e in excluded if "민영" in e["reason"] or "법인" in e["reason"]]),
        "제외_행수": len(excluded), "제외_행": excluded,
        "중복제거_행수": len(merged), "중복제거_행": merged,
        "총_주차장": len(card),
        "노외_부설": dict(Counter(l["ptype"] for l in card)),
        "노상_구간": len(street),
        "총_구획수": sum(l["spaces"] or 0 for l in card),
        "노상_구획수": sum(l["spaces"] or 0 for l in street),
        "동별": dict(sorted(Counter(l["dong"] or "동 미상" for l in card).items(),
                           key=lambda kv: (-kv[1], kv[0]))),
        "동수": len({l["dong"] for l in card if l["dong"]}),
        "동_미상": [l["name"] for l in card if not l["dong"]],
        "동_보정": dong_fixed,
        "동_근거": dict(Counter(l["dong_src"] for l in card)),
        "요금구분": dict(Counter(l["fee"]["type"] for l in lots)),
        "요금_미상": [l["name"] for l in unknown],
        "유료_노상": len([l for l in paid if l["ptype"] == "노상"]),
        "유료_노외": len([l for l in paid if l["ptype"] == "노외"]),
        "유료_부설": len([l for l in paid if l["ptype"] == "부설"]),
        "운영시간_보정": [],
        "등록값_차이": note_fixed,
        "면수_차이": space_diff,
        "급지_요금_차이": fee_diff,
        "좌표_보정": coord_fixed,
        "좌표_없음": [l["name"] for l in lots if l["lat"] is None or l["lng"] is None],
        "감면_출처": f"{conf['ordinance'][0]}({conf['ordinance'][2]})",
        "무료시간_출처": ("조례 별표 1(최초 30분 무료)·전통시장 조례 별표(최초 30분 무료)·"
                          "부설 시행규칙 별표(최초 120분 무료)의 원문(HWP, law.go.kr 첨부파일)을 "
                          "직접 확인해 대조했다"),
        "주말무료_출처": "표준데이터 운영요일·특기사항을 그대로 썼다(별표 1 비고3: 노상주차장은 공휴일 무료)",
        "무료개방_표기": [l["name"] for l in lots
                          if l["fee"]["type"] != "무료" and (l["free_days"]["sat"] or l["free_days"]["sun"])],
        "거주자우선": [],
        "무료_요금구분": len(free),
        "무료_구획수": sum(l["spaces"] or 0 for l in free),
        "평균_기본요금": round(sum(l["fee"]["base_fee"] for l in paid if l["fee"].get("base_fee"))
                            / max(1, len([l for l in paid if l["fee"].get("base_fee")]))),
        "토요일_미운영": len([l for l in lots if not l["oper"]["sat"]]),
        "일공휴일_미운영": len([l for l in lots if not l["oper"]["sun"]]),
        "주소_없음": [l["name"] for l in lots if not (l["addr_jibun"] or l["addr_road"])],
        "이름중복": [k for k, v in Counter(l["name"] for l in lots).items() if v > 1],
        "관리번호중복": [k for k, v in Counter(l.get("mgmt_no") for l in lots
                                              if l.get("mgmt_no")).items() if v > 1],
        "전화번호_없음": len([l for l in lots if not l["tel"]]),
        "데이터기준일": sorted({l["base_date"] for l in lots if l["base_date"]}),
        "관리기관": dict(Counter(l.get("manager") for l in lots)),
    }


def build_asan():
    """아산시 하나를 표준데이터 + 시 조례로 추출한다 (build_cheonan 의 아산시 변형)."""
    conf = ASAN_CONF
    rows_all = read_csv_kr(STD_CSV)

    def _owner(r):
        return (r.get("소재지지번주소") or r.get("소재지도로명주소") or "").strip()

    rows_std = [r for r in rows_all if "아산시" in _owner(r)]

    def _plot(r):
        return re.sub(r"\s+", "", (r.get("소재지지번주소") or "").strip()
                      or (r.get("소재지도로명주소") or "").strip())

    def _rank(i):
        r = rows_std[i]
        return (r.get("데이터기준일자") or "",
                1 if (r.get("요금정보") or "").strip() != "무료" else 0,
                1 if "시설관리공단" in (r.get("관리기관명") or "") else 0,
                to_int(r.get("주차구획수")) or 0)

    # 중복 판정 (청주에서 확정된 가드): 이름만으로 합치지 않는다 — 정규화 이름이 같고
    #   주소(자리)가 같고 좌표가 200m 이내일 때만 같은 주차장의 재등록으로 본다.
    #   아산은 제공기관이 둘(아산시청 43행·아산시시설관리공단 28행)이라 관리번호가
    #   서로 다른 주차장에 겹쳐 쓰인다(10개 번호) — 관리번호로는 절대 합치지 않는다.
    dropped, merged = set(), []
    group = {}
    for i, r in enumerate(rows_std):
        group.setdefault((_sj_base_name(r.get("주차장명")),
                          _plot(r)), []).append(i)
    for key, idxs in group.items():
        if len(idxs) < 2 or not key[0] or not key[1]:
            continue
        _coords = []
        for i in idxs:
            try:
                _coords.append((float(rows_std[i].get("위도") or ""),
                                float(rows_std[i].get("경도") or "")))
            except (TypeError, ValueError):
                pass
        if len(_coords) == len(idxs) and len(_coords) > 1:
            _far = max(111000 * math.sqrt((_a[0] - _b[0]) ** 2 + ((_a[1] - _b[1]) * 0.81) ** 2)
                       for _a in _coords for _b in _coords)
            if _far > 200:
                continue
        keep = max(idxs, key=_rank)
        for i in idxs:
            if i != keep:
                dropped.add(i)
        for i in idxs:
            if i == keep:
                continue
            merged.append({"name": rows_std[i]["주차장명"], "addr": _owner(rows_std[i]),
                           "spaces": to_int(rows_std[i].get("주차구획수")),
                           "note": ("같은 이름·같은 자리·좌표 200m 이내의 재등록(제공기관만 다름)"
                                    " — 최근 등록만 남김"),
                           "base_date": rows_std[i].get("데이터기준일자"),
                           "kept": rows_std[keep]["주차장명"]})
    dedup_items = [(i, rows_std[i]) for i in range(len(rows_std)) if i not in dropped]

    lots, excluded = [], []
    note_fixed, fee_diff, dong_fixed, space_diff, coord_fixed = [], [], [], [], []
    for _i, r in dedup_items:
        std_name = (r.get("주차장명") or "").strip()
        jibun = (r.get("소재지지번주소") or "").strip()
        road = (r.get("소재지도로명주소") or "").strip()
        ptype = (r.get("주차장유형") or "").strip() or "노외"
        spaces = to_int(r.get("주차구획수"))
        gubun = (r.get("주차장구분") or "").strip()
        try:
            lat = float(r["위도"]) if (r.get("위도") or "").strip() else None
            lng = float(r["경도"]) if (r.get("경도") or "").strip() else None
        except ValueError:
            lat = lng = None
        if lat is not None and lng is not None and not (36.5 < lat < 37.1 and 126.7 < lng < 127.3):
            # 아산시 경계 상자 밖 좌표는 등록 오류로 보고 비운다 (좌표를 지어내지 않는다).
            coord_fixed.append(f"{std_name}: 등록 좌표({lat}, {lng})가 아산시 범위 밖 — "
                               "좌표 없음으로 표기")
            lat = lng = None
        if gubun and gubun != "공영":
            excluded.append({"name": std_name or "(이름 없음)", "reason": f"{gubun} 주차장(공영 아님)"})
            continue
        reason = None
        if not std_name:
            reason = "주차장명 없음"
        elif not spaces:
            reason = "주차구획수 없음"
        elif not (jibun or road):
            reason = "주소 없음"
        if reason:
            excluded.append({"name": std_name or "(이름 없음)", "reason": reason})
            continue
        dong = asan_dong_of(jibun, std_name) or asan_dong_of(road, std_name)
        dong_src = "지번주소" if asan_dong_of(jibun, std_name) else ("도로명주소" if dong else "없음")
        win, oper, _closed = parse_schedule(r, (r.get("특기사항") or ""))
        note = r.get("특기사항") or ""
        note_bits, free_days = [], {"sat": False, "sun": False}
        fee = asan_fee(r, std_name, note_bits, fee_diff)
        if fee["type"] == "무료":
            note_bits.append("요금을 받지 않는 무료 공영주차장입니다")
        if "5일장" in note:
            note_bits.append("풍물 5일장날(매월 4·9·14·19·24·29일)에는 이용할 수 없고,"
                             " 5일장 전날 22:00까지 출차하지 않으면 견인될 수 있습니다(특기사항)")
        if ptype == "노상":
            # 별표 1 비고3나: 노상주차장은 공휴일 무료 운영.
            free_days = {"sat": False, "sun": True}
            note_bits.append("노상주차장은 조례 별표 1 비고3에 따라 공휴일에 무료로 운영합니다")
        if lat is None or lng is None:
            note_bits.append("좌표가 등록되어 있지 않아 지도는 주소·이름 검색으로 연결합니다")
        road_name = sj_road_of(road) if ptype == "노상" else None
        mgmt = (r.get("관리기관명") or "").strip()
        lots.append({
            "id": "", "mgmt_no": (r.get("주차장관리번호") or "").strip(),
            "src": "표준데이터", "list_mode": "street" if ptype == "노상" else "card",
            "name": std_name, "gu": "아산시", "dong": dong, "dong_src": dong_src,
            "kind": gubun or "공영", "ptype": ptype,
            "addr_jibun": jibun, "addr_road": road, "road": road_name,
            "spaces": spaces, "tel": (r.get("전화번호") or "").strip(),
            "lat": lat, "lng": lng,
            "base_date": (r.get("데이터기준일자") or "").strip(),
            "manager": mgmt or conf["manager"],
            "note": note, "notice": " · ".join(b for b in note_bits if b) or None,
            "fee": fee, "oper": oper, "hours": win, "free_days": free_days,
            "free_window": None, "free_hour_note": None,
            "closed_from_note": _closed,
            "disabled_area": (r.get("장애인전용주차구역보유여부") or "").strip(),
            "capa_detail": None, "portal_name": None, "realtime": None, "udc_id": None,
            "price_key": fee["base_fee"] if fee["type"] == "유료" else None,
            "city": conf["city"], "city_slug": conf["slug"],
            "zone": None,
        })

    _name_dups = {k for k, v in Counter(l["name"] for l in lots).items() if v > 1}
    if _name_dups:
        _used = set()
        _groups = {}
        for x in lots:
            _groups.setdefault(x["name"], []).append(x)
        for _l in [x for x in lots if x["name"] in _name_dups]:
            _parts = (_l.get("addr_jibun") or _l.get("addr_road") or "").split()
            _tail = " ".join(_parts[2:]) if len(_parts) > 2 else ""
            _sib = [x for x in _groups[_l["name"]] if x is not _l]
            _same_place = any((x.get("addr_jibun") or x.get("addr_road")) ==
                              (_l.get("addr_jibun") or _l.get("addr_road")) for x in _sib)
            if _l["list_mode"] == "street":
                _suffix = f"(노상 {_l['spaces']}면)"
            elif _tail and not _same_place:
                _suffix = f"({_tail})"
            else:
                _suffix = f"({_l['spaces']}면)"
            _cand = f"{_l['name']}{_suffix}"
            _n = 2
            while _cand in _used:
                _cand = f"{_l['name']}{_suffix} #{_n}"
                _n += 1
            _used.add(_cand)
            _l["name"] = _cand
            _l["notice"] = " · ".join(x for x in (
                _l.get("notice"),
                f"같은 이름의 주차장·구간이 여럿 등록되어 있어 이름 뒤{_suffix}로 구분했습니다") if x)
        dong_fixed.append("이름이 겹치는 주차장 " + ", ".join(sorted(_name_dups))
                          + " — 이름 뒤에 주소·면수·구간 표시를 붙여 구분")

    lots.sort(key=lambda l: (l["list_mode"] != "card", l["dong"] or "힣", l["name"]))
    n_card = n_street = 0
    for l in lots:
        if l["list_mode"] == "card":
            n_card += 1
            l["id"] = f"ca-asan-{n_card:03d}"
        else:
            n_street += 1
            l["id"] = f"ca-asan-s{n_street:03d}"

    fee_table = asan_fee_table(conf, lots)
    quality = asan_quality(conf, rows_all, rows_std, lots, excluded, merged, note_fixed,
                           fee_diff, space_diff, dong_fixed, coord_fixed)
    city_fee_src = {
        "id": "std", "name": "전국주차장정보표준데이터",
        "org": "행정안전부·지방자치단체",
        "url": "https://www.data.go.kr/data/15012896/standard.do",
        "file": STD_CSV.name, "sha256": sha256(STD_CSV),
        "license": "이용허락범위 안내(공공누리 유형별 표기)", "base_date": "2026-04-16",
        "rows_total": len(rows_all), "rows_city": len(rows_std),
        "fetched_at": "2026-11-16 22:03 (KST)",
        "note": (f"아산시로 등록된 행 {len(rows_std)}행(노외·부설 "
                 f"{len([r for r in rows_std if (r.get('주차장유형') or '') != '노상'])}·노상 "
                 f"{len([r for r in rows_std if (r.get('주차장유형') or '') == '노상'])})을 읽어 노외·부설 "
                 f"{len([l for l in lots if l['list_mode'] == 'card'])}곳과 노상 "
                 f"{len([l for l in lots if l['list_mode'] == 'street'])}구간을 실었다. 제공기관이 둘"
                 "(아산시청·아산시시설관리공단)이라 관리번호가 서로 다른 주차장에 겹쳐 쓰여"
                 " 관리번호로는 합치지 않았고, 이름·주소·좌표(200m 이내)가 모두 같은 재등록만"
                 " 합쳤다. 요금·운영시간·면수는 등록값과 특기사항을 쓰고 조례 별표와 대조했다."),
    }
    sources = [
        city_fee_src,
        {
            "id": "city_ordinance", "name": conf["ordinance"][0],
            "org": conf["manager"], "url": conf["ordinance"][1],
            "file": ASAN_ORD1_TXT.name if ASAN_ORD1_TXT.exists() else None,
            "sha256": sha256(ASAN_ORD1_TXT) if ASAN_ORD1_TXT.exists() else None,
            "license": "자치법규(공개)", "base_date": conf["ordinance"][2],
            "rows_total": None, "fetched_at": _sync_time(ASAN_ORD1_TXT) if ASAN_ORD1_TXT.exists() else None,
            "note": f"아산시가 설치·관리하는 공영주차장에 적용하는 조례다. {conf['notes']} "
                    f"(조례 본문 원자료: {ASAN_ORD_TXT.name if ASAN_ORD_TXT.exists() else 'law.go.kr'} · "
                    f"전통시장 별표: {ASAN_MARKET_TXT.name} · 부설 별표: {ASAN_BUSUL_TXT.name})",
        },
    ]
    payload = {
        "meta": {
            "generated_at": NOW.strftime("%Y-%m-%d %H:%M"),
            "generated_at_iso": NOW.isoformat(timespec="seconds"),
            "snapshot_at": NOW.strftime("%Y-%m-%d %H:%M"),
            "region": {"province": ASAN_PROVINCE, "city": conf["city"]},
            "sources": sources,
        },
        "districts": [{"name": "아산시", "slug": "asan"}],
        "lots": lots,
        "quality": quality,
        "fee_table": fee_table,
    }
    payload.update({
        "slug": conf["slug"], "province": ASAN_PROVINCE,
        "province_slug": ASAN_PROVINCE_SLUG,
        "dong_page_min_lots": 3, "city": conf["city"],
        "weekend_free_pages": False,
        "discounts": conf["discounts"],
        "city_discounts": [],
        "realtime": False,
    })
    (DATA / "asan_parking.json").write_text(json.dumps(payload, ensure_ascii=False, indent=1))
    return payload


def ca_dong_of(addr, name=None):
    """천안시 주소에서 법정동·읍·면을 읽는다 — 구 다음 낱말이 동·읍·면이다."""
    if addr:
        m = re.search(r"\(([가-힣]{1,5}(?:동|읍|면))\)", addr)
        if m:
            return m.group(1)
        parts = addr.split()
        for i, tok in enumerate(parts):
            if tok.endswith("구") and i + 1 < len(parts) \
                    and parts[i + 1].endswith(("동", "읍", "면")):
                return parts[i + 1]
            if tok.endswith("구") and i + 1 < len(parts) \
                    and re.fullmatch(r"[가-힣]{1,5}리", parts[i + 1]):
                return parts[i + 1]
            if tok.endswith(("읍", "면")) and i + 1 < len(parts) \
                    and re.fullmatch(r"[가-힣]{1,5}리", parts[i + 1]):
                return parts[i + 1]
    if name:
        m = re.search(r",\s*([가-힣]{1,5}(?:동|읍|면))\s+\d", name)
        if m:
            return m.group(1)
    return None


def _ca_won(s):
    return int(str(s).replace(",", "")) if s else None


def cheonan_fee(row, name, note_bits, fee_diff):
    """천안시 공영주차장 한 곳의 요금 — 등록값·특기사항 요율을 쓰고 조례와 대조한다."""
    raw_type = (row.get("요금정보") or "").strip()
    base_min = to_int(row.get("주차기본시간"))
    base_fee = to_int(row.get("주차기본요금"))
    unit_min = to_int(row.get("추가단위시간"))
    unit_fee = to_int(row.get("추가단위요금"))
    day = to_int(row.get("1일주차권요금"))
    month = to_int(row.get("월정기권요금"))
    note = row.get("특기사항") or ""
    fee = {"type": "유료", "base_min": None, "base_fee": None, "unit_min": None, "unit_fee": None,
           "daily_fee": None, "daily_hours": None, "cap_fee": None, "cap_src": None,
           "monthly": None, "monthly_all": None, "monthly_label": None,
           "grade": None, "grade_label": None, "std_grade": (row.get("급지구분") or "").strip() or None,
           "deduct_min": None, "free_min": None, "ticket_only": False, "flat_day": False,
           "mixed": raw_type == "혼합", "progressive": False,
           "pay": (row.get("결제방법") or "").strip(), "std": None}
    if raw_type == "무료":
        fee.update({"type": "무료", "basis": "요금 구분 ‘무료’"})
        return fee
    if raw_type not in ("유료", "혼합"):
        fee.update({"type": "미상", "basis": "요금 칸이 비어 있음"})
        return fee
    if not (base_fee or 0) and not (unit_fee or 0) and not day and not month:
        fee.update({"type": "미상", "basis": "‘유료’로 등록됐지만 요금표 등록값이 없음"})
        fee["std"] = {"base_min": base_min, "base_fee": base_fee, "unit_min": unit_min,
                      "unit_fee": unit_fee, "day": day, "monthly": month}
        return fee
    # 특기사항의 요율 문구 — ‘최초30분 무료 / 30분초과 시 10분마다 200원(2시간 이내)
    #   +2시간 초과 시 10분마다 300원’ 같은 누진 표기를 단계 요금으로 옮긴다.
    mgmt_no = (row.get("주차장관리번호") or "").strip()
    ptype = (row.get("주차장유형") or "").strip()
    if mgmt_no == "301-2-000018":
        # 목천 캠핑카전용주차장 — Instinct 교차검증 보류 1번. 별표1 캠핑카 주차요금은
        #   월정기만 있고 시간제가 없다(천안도시공사 공식 요금안내: 소형 50,000·중형
        #   80,000·대형 120,000원(천안 등록), 천안 외 등록 80,000·100,000·150,000원;
        #   사전예약제, 2026년 11월 공지). 등록 시간제(최초 30분 무료·10분 100원)는
        #   별표와 맞지 않아 쓰지 않는다.
        fee.update({"base_min": None, "base_fee": None, "unit_min": None, "unit_fee": None,
                    "daily_fee": None, "monthly": 50_000, "monthly_all": 50_000,
                    "monthly_label": "소형 기준 · 중 80,000·대 120,000원(천안 등록), "
                                     "타지역 80,000·100,000·150,000원",
                    "monthly_only": True, "free_min": None,
                    "basis": "천안시 주차장 조례 별표1 캠핑카 주차요금"
                             "(천안도시공사 공식 요금안내)"})
        note_bits.append("월정기 전용 주차장으로 시간제는 없습니다 — 소형 50,000원·중형 80,000원·"
                         "대형 120,000원(천안시 등록 기준), 천안 외 등록은 80,000원·100,000원·"
                         "150,000원입니다. 사전예약제로 운영합니다(천안도시공사 2026년 11월 공지)")
        fee["std"] = {"base_min": base_min, "base_fee": base_fee, "unit_min": unit_min,
                      "unit_fee": unit_fee, "day": day, "monthly": month}
        return fee
    m_free = re.search(r"최초\s*(\d+)\s*분\s*무료", note)
    free_min = int(m_free.group(1)) if m_free else None
    m_step = re.search(r"10분마다\s*([\d,]+)원\((\d+)시간 ?이내\)\s*\+\s*(\d+)시간 초과 시 10분마다\s*([\d,]+)원",
                       note)
    if m_step:
        u1, until_h, _h2, u2 = (_ca_won(m_step.group(1)), int(m_step.group(2)),
                                int(m_step.group(3)), _ca_won(m_step.group(4)))
        until = until_h * 60
        fee.update({"base_min": free_min or base_min or 30, "base_fee": 0,
                    "free_min": free_min or 30,
                    "unit_min": 10, "unit_fee": u1, "progressive": True,
                    "steps": [{"until": until, "unit_min": 10, "unit_fee": u1},
                              {"until": None, "unit_min": 10, "unit_fee": u2}],
                    "steps_label": (f"{until_h}시간까지 10분당 {u1:,}원 → "
                                    f"{until_h}시간 초과 10분당 {u2:,}원"),
                    "basis": "표준데이터 특기사항 요율(조례 별표1 교차확인)"})
        if unit_fee and unit_fee != u1:
            fee_diff.append(f"{name}: 추가단위요금 등록 10분 {unit_fee:,}원 ↔ 특기사항 요율 "
                            f"10분 {u1:,}원({until_h}시간 이내) — 특기사항을 따름")
        tier = None
        if u1 == CHEONAN_FEE["std1"]["unit_fee"] and u2 == CHEONAN_FEE["std1"]["over_fee"]:
            tier = "std1"
            fee["grade"] = 1
            fee["grade_label"] = "1급지"
        elif u1 == CHEONAN_FEE["transfer"]["unit_fee"] and u2 == CHEONAN_FEE["transfer"]["over_fee"]:
            tier = "transfer"
            fee["grade_label"] = "환승주차장"
        if tier:
            tf = CHEONAN_FEE[tier]
            if day and day != tf["day"]:
                fee_diff.append(f"{name}: 1일 주차권 등록 {day:,}원 ↔ 교차확인 요율 {tf['day']:,}원")
            if month and month != tf["month"]:
                fee_diff.append(f"{name}: 월 정기 등록 {month:,}원 ↔ 교차확인 요율 {tf['month']:,}원")
        fee["daily_fee"] = day or (CHEONAN_FEE[tier]["day"] if tier else None)
        if ptype == "노상" and day:
            # Instinct 교차검증 보류 3번 — 대흥로 제1노상. 조례 별표1 비고6: 1일주차권·
            #   월주차권은 노외주차장에 한함. 등록 1일권이 있어도 노상에는 표시하지 않는다.
            fee["daily_fee"] = None
            fee_diff.append(f"{name}: 등록 1일 {day:,}원이 있으나 조례 별표1 비고6"
                            "(1일·월주차권은 노외주차장에 한함)에 따라 노상 1일권 표시 제외")
            note_bits.append("노상주차장은 조례 별표1 비고6에 따라 1일주차권을 실시하지 않습니다"
                             f"(등록 1일 {day:,}원은 표시하지 않음)")
        note_bits.append(f"요율은 특기사항 기준 최초 {fee['free_min']}분 무료, {until_h}시간까지 "
                         f"10분마다 {u1:,}원, {until_h}시간 초과 10분마다 {u2:,}원입니다")
    elif base_fee:
        # 전통시장 주차장·주민센터처럼 기본요금부터 받는 등록 형태.
        fee.update({"base_min": base_min or 30, "base_fee": base_fee,
                    "unit_min": unit_min or 10, "unit_fee": unit_fee,
                    "daily_fee": day,
                    "basis": "표준데이터 등록요금(조례 별표1 원문 대조 미확정)"})
        if "전통시장" in note:
            note_bits.append("전통시장 이용자는 특기사항 기준으로 1시간 무료입니다")
        if "시장" in name:
            # Instinct 교차검증 보류 2번 — 별표1 원문(HWP) 확인 결과 시장 전용 요율은
            #   별표에 없음(비고5는 시장이 정하는 경우 50% 범위 내 할인만 허용). 등록
            #   500원 기본요율은 1급지 표준(최초 30분 무료)과 달라, 운영 근거 확인 전까지
            #   등록값을 그대로 표기하고 차이를 명시한다.
            #   (5단지시장은 특기사항이 비어 있어 이름으로 판정한다.)
            note_bits.append("기본 30분 500원은 등록 요율입니다 — 조례 별표1 1급지 표준 요율"
                             "(최초 30분 무료)과 달라 운영 근거를 확인 중입니다"
                             "(별표1 원문에는 시장 전용 요율이 없습니다)")
            fee["basis"] = ("표준데이터 등록요금 — 별표1 원문(HWP) 확인 결과 시장 전용 요율 없음"
                            "(비고5는 50% 범위 내 할인만 허용), 1급지 표준과 달라 운영 근거 확인 중")
        if (row.get("급지구분") or "").strip() == "1":
            fee_diff.append(f"{name}: 1급지로 등록됐지만 기본 {base_min or 30}분 {base_fee:,}원부터 "
                            "과금 — 1급지 표준 요율(최초 30분 무료·누진)과 달라 별표1 원문(HWP) 확인 결과 "
                            "시장 전용 요율 없음(비고5는 50% 범위 내 할인만 허용), 운영 근거 확인 전까지 등록값 표기")
    else:
        # 기본요금 0원 + 단위요금만 등록된 곳(목천 캠핑카전용) — 최초 기본시간 무료로 읽는다.
        fee.update({"base_min": base_min or 30, "base_fee": 0,
                    "free_min": free_min or base_min or 30,
                    "unit_min": unit_min or 10, "unit_fee": unit_fee,
                    "daily_fee": day,
                    "basis": "표준데이터 등록요금(최초 무료 뒤 단위요금)"})
        note_bits.append(f"최초 {fee['free_min']}분이 무료이고 그 뒤 {fee['unit_min']}분마다 "
                         f"{unit_fee or 0:,}원입니다")
    if month:
        fee["monthly_all"] = month
        fee["monthly_label"] = "전일"
    fee["monthly"] = fee["monthly_all"]
    if raw_type == "혼합":
        m_paid_hours = re.search(r"유료 운영시간:\s*([^/]+)", note)
        if m_paid_hours:
            note_bits.append(f"유료 운영시간은 {m_paid_hours.group(1).strip()}입니다(특기사항)")
        else:
            note_bits.append("요금 구분이 ‘혼합’이라 요금을 받는 시간에만 계산합니다")
    if mgmt_no == "302-2-000111":
        # 노태공원공영주차장 — Instinct 교차검증 보류 4번. 도시공원 공영주차장으로,
        #   주차장 조례 별표1이 아니라 「천안시 도시공원 공영주차장 관리 운영 조례」
        #   제7조 요금표를 적용한다(최초 120분 무료·400원·500원·1일 5,000원,
        #   천안도시공사 공식 요금안내와 일치). 요율 값은 그대로 두고 근거만 정정한다.
        fee["basis"] = ("천안시 도시공원 공영주차장 관리 운영 조례 제7조제1항"
                        "(도시공원 공영주차장 요금표)")
        note_bits.append("도시공원 공영주차장으로, 「천안시 도시공원 공영주차장 관리 운영 조례」"
                         " 제7조 요금표를 적용합니다")
    fee["std"] = {"base_min": base_min, "base_fee": base_fee, "unit_min": unit_min,
                  "unit_fee": unit_fee, "day": day, "monthly": month}
    return fee


def _ca_tier_of(lot):
    """요금표 묶음 판정 — 단계 요금이면 1급지/환승, 기본요금형이면 시장형으로 본다."""
    f = lot["fee"]
    steps = f.get("steps")
    if steps:
        if steps[0]["unit_fee"] == 100 and steps[-1]["unit_fee"] == 200:
            return "transfer"
        if steps[0].get("until") == 120 and steps[0]["unit_fee"] == 200 \
                and steps[-1]["unit_fee"] == 300:
            return "std1"
        return "other"
    if f.get("base_fee"):
        return "market"
    return "other"


def cheonan_fee_table(conf, lots):
    """요금표 — 교차확인한 요율 3묶음(1급지 누진·환승·기본요금형)."""
    paid = [l for l in lots if l["fee"]["type"] == "유료"]
    g1 = CHEONAN_FEE["std1"]
    tr = CHEONAN_FEE["transfer"]
    samples = {
        "std1": {"base_min": 30, "base_fee": 0, "free_min": 30, "unit_min": 10,
                 "unit_fee": g1["unit_fee"], "daily_fee": g1["day"],
                 "steps": [{"until": 120, "unit_min": 10, "unit_fee": g1["unit_fee"]},
                           {"until": None, "unit_min": 10, "unit_fee": g1["over_fee"]}]},
        "transfer": {"base_min": 30, "base_fee": 0, "free_min": 30, "unit_min": 10,
                     "unit_fee": tr["unit_fee"], "daily_fee": tr["day"],
                     "steps": [{"until": 120, "unit_min": 10, "unit_fee": tr["unit_fee"]},
                               {"until": None, "unit_min": 10, "unit_fee": tr["over_fee"]}]},
        "market": {"base_min": 30, "base_fee": 500, "unit_min": 10, "unit_fee": 200,
                   "daily_fee": 10_000},
    }
    labels = {
        "std1": ("1급지", "최초 30분 무료 → 2시간까지 10분마다 200원 → 2시간 초과 10분마다 300원"),
        "transfer": ("환승주차장", "최초 30분 무료 → 2시간까지 10분마다 100원 → 2시간 초과 10분마다 200원"),
        "market": ("기본요금형(시장 등 · 월정기는 등록된 곳만)", "기본 30분 500원 → 10분마다 200원"),
    }
    rows = []
    for key in ("std1", "transfer", "market"):
        gl = [l for l in paid if _ca_tier_of(l) == key]
        if not gl:
            continue
        sf = samples[key]
        rows.append({"label": labels[key][0], "grade": key,
                     "unit_label": labels[key][1],
                     "hour": sj_charge(sf, 60), "two_hour": sj_charge(sf, 120),
                     "day": sf["daily_fee"],
                     "month": (g1["month"] if key == "std1" else
                               tr["month"] if key == "transfer" else 80_000),
                     "lots": len(gl)})
    ord_rows = [
        {"label": "1급지", "base": 0, "unit": 200, "day": g1["day"], "month": g1["month"]},
        {"label": "환승주차장", "base": 0, "unit": 100, "day": tr["day"], "month": tr["month"]},
    ]
    corp = {
        "paid": len([l for l in paid if l["list_mode"] == "card"]),
        "free": len([l for l in lots if l["fee"]["type"] == "무료"]),
        "unknown": len([l for l in lots if l["fee"]["type"] == "미상"]),
        "street_paid": len([l for l in paid if l["list_mode"] == "street"]),
    }
    return {
        "style": "cheonan_grade",
        "unit_min": 10,
        "base_min": 30,
        "applies": conf["ordinance"][2],
        "rows": rows,
        "ord_rows": ord_rows,
        "corp": corp,
        "windows": [{"group": "공통", "hours": "주차장별 운영시간",
                     "free": ("조례 별표1 원문은 첨부파일로만 제공되어, 요금은 표준데이터에 "
                              "등록된 주차장별 운영시간·특기사항을 카드에 그대로 적었습니다")}],
        "notes": conf["notes"],
        "corp_extra": corp,
        "basis": (f"{conf['ordinance'][0]}({conf['ordinance'][2]}) · "
                  "전국주차장정보표준데이터(2026-04-16 기준) 등록값·특기사항 대조"),
    }


def cheonan_quality(conf, std_all, rows_std, lots, excluded, merged, note_fixed, fee_diff,
                    space_diff, dong_fixed):
    card = [l for l in lots if l["list_mode"] == "card"]
    street = [l for l in lots if l["list_mode"] == "street"]
    paid = [l for l in lots if l["fee"]["type"] == "유료"]
    free = [l for l in lots if l["fee"]["type"] == "무료"]
    unknown = [l for l in lots if l["fee"]["type"] == "미상"]
    return {
        "generated_at": NOW.strftime("%Y-%m-%d %H:%M"),
        "원자료_전국행수": len(std_all),
        "원자료_행수": len(rows_std),
        f"원자료_{conf['city']}행수": len(rows_std),
        "원자료_받은행수": len(rows_std),
        "구별": dict(sorted(Counter(l["gu"] for l in card).items())),
        "민영_제외": len([e for e in excluded if "민영" in e["reason"] or "법인" in e["reason"]]),
        "제외_행수": len(excluded), "제외_행": excluded,
        "중복제거_행수": len(merged), "중복제거_행": merged,
        "총_주차장": len(card),
        "노외_부설": dict(Counter(l["ptype"] for l in card)),
        "노상_구간": len(street),
        "총_구획수": sum(l["spaces"] or 0 for l in card),
        "노상_구획수": sum(l["spaces"] or 0 for l in street),
        "동별": dict(sorted(Counter(l["dong"] or "동 미상" for l in card).items(),
                           key=lambda kv: (-kv[1], kv[0]))),
        "동수": len({l["dong"] for l in card if l["dong"]}),
        "동_미상": [l["name"] for l in card if not l["dong"]],
        "동_보정": dong_fixed,
        "동_근거": dict(Counter(l["dong_src"] for l in card)),
        "요금구분": dict(Counter(l["fee"]["type"] for l in lots)),
        "요금_미상": [l["name"] for l in unknown],
        "유료_노상": len([l for l in paid if l["ptype"] == "노상"]),
        "유료_노외": len([l for l in paid if l["ptype"] == "노외"]),
        "유료_부설": len([l for l in paid if l["ptype"] == "부설"]),
        "운영시간_보정": [],
        "등록값_차이": note_fixed,
        "면수_차이": space_diff,
        "급지_요금_차이": fee_diff,
        "좌표_보정": [],
        "좌표_없음": [l["name"] for l in lots if l["lat"] is None or l["lng"] is None],
        "감면_출처": f"{conf['ordinance'][0]}({conf['ordinance'][2]})",
        "무료시간_출처": ("표준데이터 특기사항의 ‘최초 N분 무료’ 표기를 그대로 썼다. "
                          "조례 별표1 원문(HWP, law.go.kr 첨부파일)을 직접 확인해 1급지·2급지·"
                          "환승·캠핑카 요율과 비고 1~9를 원문으로 대조했다"),
        "주말무료_출처": "표준데이터 운영요일·특기사항을 그대로 썼다(대흥로 제1노상 ‘주말·공휴일 무료 운영’)",
        "무료개방_표기": [l["name"] for l in lots
                          if l["fee"]["type"] != "무료" and (l["free_days"]["sat"] or l["free_days"]["sun"])],
        "거주자우선": [],
        "무료_요금구분": len(free),
        "무료_구획수": sum(l["spaces"] or 0 for l in free),
        "평균_기본요금": round(sum(l["fee"]["base_fee"] for l in paid if l["fee"].get("base_fee"))
                            / max(1, len([l for l in paid if l["fee"].get("base_fee")]))),
        "토요일_미운영": len([l for l in lots if not l["oper"]["sat"]]),
        "일공휴일_미운영": len([l for l in lots if not l["oper"]["sun"]]),
        "주소_없음": [l["name"] for l in lots if not (l["addr_jibun"] or l["addr_road"])],
        "이름중복": [k for k, v in Counter(l["name"] for l in lots).items() if v > 1],
        "관리번호중복": [k for k, v in Counter(l.get("mgmt_no") for l in lots
                                              if l.get("mgmt_no")).items() if v > 1],
        "전화번호_없음": len([l for l in lots if not l["tel"]]),
        "데이터기준일": sorted({l["base_date"] for l in lots if l["base_date"]}),
        "관리기관": dict(Counter(l.get("manager") for l in lots)),
    }


def build_cheonan():
    """천안시 하나를 표준데이터 + 시 조례로 추출한다 (build_cheongju 의 충청남도 변형)."""
    conf = CHEONAN_CONF
    rows_all = read_csv_kr(STD_CSV)

    def _owner(r):
        return (r.get("소재지지번주소") or r.get("소재지도로명주소") or "").strip()

    rows_std = [r for r in rows_all if "천안시" in _owner(r)]

    def _plot(r):
        return re.sub(r"\s+", "", (r.get("소재지지번주소") or "").strip()
                      or (r.get("소재지도로명주소") or "").strip())

    def _rank(i):
        r = rows_std[i]
        return (r.get("데이터기준일자") or "",
                1 if (r.get("요금정보") or "").strip() != "무료" else 0,
                1 if "도시공사" in (r.get("관리기관명") or "") else 0,
                to_int(r.get("주차구획수")) or 0)

    dropped, merged = set(), []
    by_no = {}
    for i, r in enumerate(rows_std):
        no = (r.get("주차장관리번호") or "").strip()
        if no:
            by_no.setdefault(no, []).append(i)
    for no, idxs in by_no.items():
        # 천안은 같은 관리번호를 서로 다른 주차장이 나눠 쓰는 행이 4쌍 있다
        #   (예: 301-2-000030 신방 제1 ↔ 천안역전시장1). 자리(주소)가 같을 때만 합친다.
        if len(idxs) < 2 or len({_plot(rows_std[i]) for i in idxs}) > 1:
            continue
        keep = max(idxs, key=_rank)
        names = sorted({rows_std[i]["주차장명"] for i in idxs})
        for i in idxs:
            if i != keep:
                dropped.add(i)
        for i in idxs:
            if i == keep:
                continue
            merged.append({"name": " / ".join(names) if len(names) > 1 else rows_std[i]["주차장명"],
                           "addr": _owner(rows_std[i]),
                           "spaces": to_int(rows_std[i].get("주차장구획수") or rows_std[i].get("주차구획수")),
                           "note": ("같은 주차장관리번호·같은 자리로 두 번 등록(관리기관 표기만 다름) — 최근 등록만 남김"
                                    if len(names) > 1 else
                                    "같은 주차장관리번호·같은 자리의 같은 등록(스냅숏 중복) — 하나만 남김"),
                           "base_date": rows_std[i].get("데이터기준일자"),
                           "kept": rows_std[keep]["주차장명"]})
    rest = [i for i in range(len(rows_std)) if i not in dropped]
    group = {}
    for i in rest:
        r = rows_std[i]
        group.setdefault((_sj_base_name(r.get("주차장명")),
                          ca_dong_of(r.get("소재지지번주소") or r.get("소재지도로명주소"),
                                     r.get("주차장명")),
                          to_int(r.get("주차구획수")) or 0), []).append(i)
    for key, idxs in group.items():
        if len(idxs) < 2:
            continue
        # 이름 기반 중복 제거는 같은 주차장의 재등록일 때만 (청주 T-03 교차검증 가드와 동일):
        # 이름이 비었거나 유형·구가 다르거나 주소·좌표가 다르면 합치지 않는다.
        if not key[0]:
            continue
        _ptypes = {(rows_std[i].get("주차장유형") or "").strip() for i in idxs}
        _gus = {ca_gu_of(_owner(rows_std[i])) for i in idxs}
        if len(_ptypes) > 1 or len(_gus) > 1:
            continue
        _plots = {_plot(rows_std[i]) for i in idxs}
        if len(_plots) > 1:
            continue
        _coords = []
        for i in idxs:
            try:
                _coords.append((float(rows_std[i].get("위도") or ""),
                                float(rows_std[i].get("경도") or "")))
            except (TypeError, ValueError):
                pass
        if len(_coords) == len(idxs) and len(_coords) > 1:
            _far = max(111000 * math.sqrt((_a[0] - _b[0]) ** 2 + ((_a[1] - _b[1]) * 0.81) ** 2)
                       for _a in _coords for _b in _coords)
            if _far > 200:
                continue
        keep = max(idxs, key=_rank)
        for i in idxs:
            if i != keep:
                dropped.add(i)
        for i in idxs:
            if i == keep:
                continue
            merged.append({"name": rows_std[i]["주차장명"], "addr": _owner(rows_std[i]),
                           "spaces": to_int(rows_std[i].get("주차구획수")),
                           "note": "같은 이름·같은 자리·같은 면수의 옛 등록(스냅숏 중복) — 최근 등록만 남김",
                           "base_date": rows_std[i].get("데이터기준일자"),
                           "kept": rows_std[keep].get("데이터기준일자")})
    dedup_items = [(i, rows_std[i]) for i in range(len(rows_std)) if i not in dropped]

    lots, excluded = [], []
    note_fixed, fee_diff, dong_fixed, space_diff = [], [], [], []
    for _i, r in dedup_items:
        std_name = (r.get("주차장명") or "").strip()
        jibun = (r.get("소재지지번주소") or "").strip()
        road = (r.get("소재지도로명주소") or "").strip()
        ptype = (r.get("주차장유형") or "").strip() or "노외"
        spaces = to_int(r.get("주차구획수"))
        gubun = (r.get("주차장구분") or "").strip()
        try:
            lat = float(r["위도"]) if (r.get("위도") or "").strip() else None
            lng = float(r["경도"]) if (r.get("경도") or "").strip() else None
        except ValueError:
            lat = lng = None
        if gubun and gubun != "공영":
            excluded.append({"name": std_name or "(이름 없음)", "reason": f"{gubun} 주차장(공영 아님)"})
            continue
        reason = None
        if not std_name:
            reason = "주차장명 없음"
        elif not spaces:
            reason = "주차구획수 없음"
        elif not (jibun or road):
            reason = "주소 없음"
        if reason:
            excluded.append({"name": std_name or "(이름 없음)", "reason": reason})
            continue
        gu = ca_gu_of(jibun) or ca_gu_of(road) or "천안시"
        dong = ca_dong_of(jibun, std_name) or ca_dong_of(road, std_name)
        dong_src = "지번주소" if ca_dong_of(jibun, std_name) else ("도로명주소" if dong else "없음")
        win, oper, _closed = parse_schedule(r, (r.get("특기사항") or ""))
        note = r.get("특기사항") or ""
        note_bits, free_days = [], {"sat": False, "sun": False}
        fee = cheonan_fee(r, std_name, note_bits, fee_diff)
        if fee["type"] == "무료":
            note_bits.append("요금을 받지 않는 무료 공영주차장입니다")
        if "환승" in note:
            note_bits.append("환승주차장으로 등록되어 있습니다")
        if "주말" in note and "무료" in note:
            free_days = {"sat": True, "sun": True}
            note_bits.append("특기사항 기준으로 주말·공휴일은 무료로 운영합니다")
        if lat is None or lng is None:
            note_bits.append("좌표가 등록되어 있지 않아 지도는 주소·이름 검색으로 연결합니다")
        road_name = sj_road_of(road) if ptype == "노상" else None
        mgmt = (r.get("관리기관명") or "").strip()
        lots.append({
            "id": "", "mgmt_no": (r.get("주차장관리번호") or "").strip(),
            "src": "표준데이터", "list_mode": "street" if ptype == "노상" else "card",
            "name": std_name, "gu": gu, "dong": dong, "dong_src": dong_src,
            "kind": gubun or "공영", "ptype": ptype,
            "addr_jibun": jibun, "addr_road": road, "road": road_name,
            "spaces": spaces, "tel": (r.get("전화번호") or "").strip(),
            "lat": lat, "lng": lng,
            "base_date": (r.get("데이터기준일자") or "").strip(),
            "manager": mgmt or conf["manager"],
            "note": note, "notice": " · ".join(b for b in note_bits if b) or None,
            "fee": fee, "oper": oper, "hours": win, "free_days": free_days,
            "free_window": None, "free_hour_note": None,
            "closed_from_note": _closed,
            "disabled_area": (r.get("장애인전용주차구역보유여부") or "").strip(),
            "capa_detail": None, "portal_name": None, "realtime": None, "udc_id": None,
            "price_key": fee["base_fee"] if fee["type"] == "유료" else None,
            "city": conf["city"], "city_slug": conf["slug"],
            "zone": None,
        })

    _known = [l for l in lots if l["dong"] and l["lat"] is not None and l["lng"] is not None]
    if _known:
        for l in lots:
            if l["dong"] or l["lat"] is None or l["lng"] is None:
                continue

            def _near_dist(o, _l=l):
                return (o["lat"] - _l["lat"]) ** 2 + ((o["lng"] - _l["lng"]) * 0.81) ** 2

            _near = min(_known, key=_near_dist)
            _d = 111000 * math.sqrt(_near_dist(_near))
            if _d <= 1500:
                l["dong"] = _near["dong"]
                l["dong_src"] = f"좌표 인근({_near['name']}, {_d:.0f}m)"
                dong_fixed.append(f"{l['name']}: 동 미상 → {_near['dong']}(좌표 {_d:.0f}m 인근 {_near['name']})")

    _name_dups = {k for k, v in Counter(l["name"] for l in lots).items() if v > 1}
    if _name_dups:
        _used = set()
        _groups = {}
        for x in lots:
            _groups.setdefault(x["name"], []).append(x)
        for _l in [x for x in lots if x["name"] in _name_dups]:
            _parts = (_l.get("addr_jibun") or _l.get("addr_road") or "").split()
            _tail = " ".join(_parts[2:]) if len(_parts) > 2 else ""
            _sib = [x for x in _groups[_l["name"]] if x is not _l]
            _same_place = any((x.get("addr_jibun") or x.get("addr_road")) ==
                              (_l.get("addr_jibun") or _l.get("addr_road")) for x in _sib)
            if _l["list_mode"] == "street":
                _suffix = f"(노상 {_l['spaces']}면)"
            elif _tail and not _same_place:
                _suffix = f"({_tail})"
            else:
                _suffix = f"({_l['spaces']}면)"
            _cand = f"{_l['name']}{_suffix}"
            _n = 2
            while _cand in _used:
                _cand = f"{_l['name']}{_suffix} #{_n}"
                _n += 1
            _used.add(_cand)
            _l["name"] = _cand
            _l["notice"] = " · ".join(x for x in (
                _l.get("notice"),
                f"같은 이름의 주차장·구간이 여럿 등록되어 있어 이름 뒤{_suffix}로 구분했습니다") if x)
        dong_fixed.append("이름이 겹치는 주차장 " + ", ".join(sorted(_name_dups))
                          + " — 이름 뒤에 주소·면수·구간 표시를 붙여 구분")

    lots.sort(key=lambda l: (l["list_mode"] != "card", l["dong"] or "힣", l["name"]))
    n_card = n_street = 0
    for l in lots:
        if l["list_mode"] == "card":
            n_card += 1
            l["id"] = f"ca-cheonan-{n_card:03d}"
        else:
            n_street += 1
            l["id"] = f"ca-cheonan-s{n_street:03d}"

    fee_table = cheonan_fee_table(conf, lots)
    quality = cheonan_quality(conf, rows_all, rows_std, lots, excluded, merged, note_fixed,
                              fee_diff, space_diff, dong_fixed)
    city_fee_src = {
        "id": "std", "name": "전국주차장정보표준데이터",
        "org": "행정안전부·지방자치단체",
        "url": "https://www.data.go.kr/data/15012896/standard.do",
        "file": STD_CSV.name, "sha256": sha256(STD_CSV),
        "license": "이용허락범위 안내(공공누리 유형별 표기)", "base_date": "2026-04-16",
        "rows_total": len(rows_all), "rows_city": len(rows_std),
        "fetched_at": "2026-11-16 22:03 (KST)",
        "note": (f"천안시로 등록된 행 {len(rows_std)}행(노외·부설 "
                 f"{len([r for r in rows_std if (r.get('주차장유형') or '') != '노상'])}·노상 "
                 f"{len([r for r in rows_std if (r.get('주차장유형') or '') == '노상'])})을 읽어 노외·부설 "
                 f"{len([l for l in lots if l['list_mode'] == 'card'])}곳과 노상 "
                 f"{len([l for l in lots if l['list_mode'] == 'street'])}구간을 실었다. 요금·운영시간·면수는 "
                 "등록값과 특기사항 요율을 쓰고 조례 제3조(면제·감면)와 대조했으며, 같은 관리번호를 "
                 "다른 주차장이 나눠 쓰는 행은 합치지 않았다."),
    }
    sources = [
        city_fee_src,
        {
            "id": "city_ordinance", "name": conf["ordinance"][0],
            "org": conf["manager"], "url": conf["ordinance"][1],
            "file": CHEONAN_ORD1_TXT.name if CHEONAN_ORD1_TXT.exists() else None,
            "sha256": sha256(CHEONAN_ORD1_TXT) if CHEONAN_ORD1_TXT.exists() else None,
            "license": "자치법규(공개)", "base_date": conf["ordinance"][2],
            "rows_total": None, "fetched_at": _sync_time(CHEONAN_ORD1_TXT) if CHEONAN_ORD1_TXT.exists() else None,
            "note": f"천안시가 설치·관리하는 공영주차장에 적용하는 조례다. {conf['notes']} "
                    f"(조례 본문 원자료: {CHEONAN_ORD_TXT.name if CHEONAN_ORD_TXT.exists() else 'law.go.kr'})",
        },
    ]
    payload = {
        "meta": {
            "generated_at": NOW.strftime("%Y-%m-%d %H:%M"),
            "generated_at_iso": NOW.isoformat(timespec="seconds"),
            "snapshot_at": NOW.strftime("%Y-%m-%d %H:%M"),
            "region": {"province": CHEONAN_PROVINCE, "city": conf["city"]},
            "sources": sources,
        },
        "districts": [{"name": gu_name, "slug": gu_slug} for gu_name, gu_slug in CHEONAN_GU],
        "lots": lots,
        "quality": quality,
        "fee_table": fee_table,
    }
    payload.update({
        "slug": conf["slug"], "province": CHEONAN_PROVINCE,
        "province_slug": CHEONAN_PROVINCE_SLUG,
        "dong_page_min_lots": 3, "city": conf["city"],
        "weekend_free_pages": False,
        "discounts": conf["discounts"],
        "city_discounts": [],
        "realtime": False,
    })
    (DATA / "cheonan_parking.json").write_text(json.dumps(payload, ensure_ascii=False, indent=1))
    return payload


SEOSAN_PROVINCE = "충청남도"
SEOSAN_PROVINCE_SLUG = "chungnam"

